import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import { CloseButton } from '../close-button';
import styles from './Tag.module.css';

type TagVariant = 'default' | 'secondary' | 'outline' | 'ghost' | 'destructive';
type TagSize = 'sm' | 'md' | 'lg';
type TagRootProps = HTMLArkProps<'span'> & {
  variant?: TagVariant;
  size?: TagSize;
};

function Tag(props: TagRootProps) {
  const [local, others] = splitProps(props, ['class', 'size', 'variant']);

  return (
    <ark.span
      {...others}
      data-scope="tag"
      data-part="root"
      data-slot="tag-root"
      data-size={local.size ?? 'md'}
      data-variant={local.variant ?? 'default'}
      class={clsx(styles.root, local.class)}
    />
  );
}

function TagLabel(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      {...others}
      data-scope="tag"
      data-part="label"
      data-slot="tag-label"
      class={clsx(styles.label, local.class)}
    />
  );
}

function TagStartElement(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      {...others}
      data-scope="tag"
      data-part="start-element"
      data-slot="tag-start-element"
      class={clsx(styles.startElement, local.class)}
    />
  );
}

function TagEndElement(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      {...others}
      data-scope="tag"
      data-part="end-element"
      data-slot="tag-end-element"
      class={clsx(styles.endElement, local.class)}
    />
  );
}

function TagCloseTrigger(props: HTMLArkProps<'button'>) {
  const [local, others] = splitProps(props, ['aria-label', 'class']);

  return (
    <CloseButton
      {...others}
      data-scope="tag"
      data-part="close-trigger"
      data-slot="tag-close-trigger"
      aria-label={
        local['aria-label'] ?? (others['aria-labelledby'] == null ? a11yLabels.closeTag : undefined)
      }
      class={clsx(styles.closeTrigger, local.class)}
    />
  );
}

export { Tag, TagCloseTrigger, TagEndElement, TagLabel, TagStartElement };
export type { TagRootProps, TagSize, TagVariant };

@layer moduix.components {
  .root {
    display: inline-flex;
    width: fit-content;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
    align-items: center;
    gap: var(--moduix-spacing-1-5);
    border: var(--moduix-border-width-sm) solid var(--moduix-tag-border-color, transparent);
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-tag-bg, var(--moduix-color-primary));
    color: var(--moduix-tag-color, var(--moduix-color-primary-foreground));
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-xs);
    min-height: var(--moduix-size-xs);
    padding-block: var(--moduix-spacing-0-5);
    padding-inline: var(--moduix-spacing-2);
    white-space: nowrap;
    vertical-align: middle;
    transition:
      color var(--moduix-transition-default),
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default);

    &:is(a, button) {
      cursor: pointer;
    }

    &[data-size='sm'] {
      gap: var(--moduix-spacing-1);
      min-height: 1.25rem;
      padding-block: 0;
      padding-inline: var(--moduix-spacing-1-5);
    }

    &[data-size='lg'] {
      min-height: 1.75rem;
      padding-inline: var(--moduix-spacing-2-5);
      font-size: var(--moduix-text-sm);
      line-height: var(--moduix-line-height-text-sm);
    }

    &[data-variant='secondary'] {
      background-color: var(--moduix-tag-bg, var(--moduix-color-secondary));
      color: var(--moduix-tag-color, var(--moduix-color-secondary-foreground));
    }

    &[data-variant='outline'] {
      border-color: var(--moduix-tag-border-color, var(--moduix-color-border));
      background-color: var(--moduix-tag-bg, transparent);
      color: var(--moduix-tag-color, var(--moduix-color-foreground));
    }

    &[data-variant='ghost'] {
      background-color: var(--moduix-tag-bg, transparent);
      color: var(--moduix-tag-color, var(--moduix-color-foreground));
    }

    &[data-variant='destructive'] {
      background-color: var(--moduix-tag-bg, var(--moduix-color-destructive));
      color: var(--moduix-tag-color, var(--moduix-color-destructive-foreground));
    }
  }

  .label {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .startElement,
  .endElement {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  .root > svg,
  .startElement > svg,
  .endElement > svg {
    width: var(--moduix-spacing-3);
    height: var(--moduix-spacing-3);
    flex-shrink: 0;
    pointer-events: none;
  }

  .closeTrigger {
    --moduix-close-button-size: var(--moduix-spacing-4);
    --moduix-close-button-radius: var(--moduix-radius-full);
    --moduix-close-button-icon-size: var(--moduix-spacing-3);
    --moduix-close-button-bg-hover: color-mix(in oklab, currentColor 12%, transparent);
    --moduix-close-button-color: currentColor;
    --moduix-close-button-color-hover: currentColor;
    --moduix-close-button-focus-ring-width: var(--moduix-focus-ring-inset-width);
    --moduix-close-button-focus-ring-offset: 0;
  }
}
